ALTER TABLE public.team_working_settings ADD COLUMN role_house jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(role_house)='object');
CREATE OR REPLACE FUNCTION public.save_team_working_settings(t uuid,p jsonb,expected jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old jsonb; item record; houses jsonb; BEGIN
IF auth.uid() IS NULL OR NOT public.user_has_tenant(auth.uid(),t) OR NOT (public.people_owner(t,auth.uid()) OR public.has_role(auth.uid(),'admin') OR public.is_super_admin(auth.uid())) THEN RAISE EXCEPTION 'Business settings administrator required'; END IF;
IF p->>'default_mode' IS NULL OR p->>'default_mode' NOT IN ('own','across','central') OR jsonb_typeof(p->'role_modes') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Choose a valid company default and role settings'; END IF;
FOR item IN SELECT key,value FROM jsonb_each_text(p->'role_modes') LOOP IF item.value NOT IN ('own','across','central') OR NOT (item.key IN ('Bar','Floor','Kitchen','Promotions','Management','Cleaning','No role set') OR EXISTS(SELECT 1 FROM public.hr_role_groups WHERE tenant_id=t AND name=item.key)) THEN RAISE EXCEPTION 'Unknown role or team mode'; END IF; END LOOP;
PERFORM pg_advisory_xact_lock(hashtextextended(t::text||'team_working_settings',0)); SELECT to_jsonb(s) INTO old FROM public.team_working_settings s WHERE tenant_id=t FOR UPDATE;
IF old IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Team settings changed; review the latest choice'; END IF;
houses:=coalesce(p->'role_house',old->'role_house','{}'::jsonb);
IF jsonb_typeof(houses) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Choose valid front/back settings'; END IF;
FOR item IN SELECT key,value FROM jsonb_each_text(houses) LOOP IF item.value NOT IN ('front','back') OR NOT (item.key IN ('Bar','Floor','Kitchen','Promotions','Management','Cleaning','No role set') OR EXISTS(SELECT 1 FROM public.hr_role_groups WHERE tenant_id=t AND name=item.key)) THEN RAISE EXCEPTION 'Unknown role or front/back choice'; END IF; END LOOP;
INSERT INTO public.team_working_settings(tenant_id,default_mode,role_modes,role_house,updated_by) VALUES(t,p->>'default_mode',p->'role_modes',houses,auth.uid()) ON CONFLICT(tenant_id) DO UPDATE SET default_mode=EXCLUDED.default_mode,role_modes=EXCLUDED.role_modes,role_house=EXCLUDED.role_house,updated_by=auth.uid(),updated_at=now();
INSERT INTO public.audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(t,auth.uid(),'update','team_working_settings',t::text,jsonb_build_object('before',old,'after',p||jsonb_build_object('role_house',houses))); END $$;
REVOKE ALL ON FUNCTION public.save_team_working_settings(uuid,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_team_working_settings(uuid,jsonb,jsonb) TO authenticated;